        makeProperty("Track3EncryptedDataLength"),
        makeProperty("Track4EncryptedData"),
        makeProperty("Track4EncryptedDataLength"),
        makeProperty("WriteCardType"),

      };

      return properties;
    }
    catch(Exception e)
