        int nLists = size(); 
        for (int n=0; n<nLists; n++) {
            Node node = getNode(n);
            String nodeName = node.getName();
            if (nodeName == null)
                continue;
            if (nodeName.endsWith(name) == true)
                return node;
        }
        return null;
    }
