    public String login(String username, String hostIp, String hostPort) {
        this.username = username;
        String login_mess = null;
        try {
            c_socket = new Socket(hostIp, Integer.parseInt(hostPort));
        } catch (NumberFormatException e) {
            login_mess = "Á¬½ÓµÄ·þÎñÆ÷¶Ë¿ÚºÅportÎªÕûÊý,È¡Öµ·¶Î§Îª£º1024<port<65535";
            return login_mess;
        } catch (UnknownHostException e) {
            login_mess = "Ö÷»úµØÖ·´íÎó";
            return login_mess;
        } catch (IOException e) {
            login_mess = "Á¬½Ó·þÎñÆäÊ§°Ü£¬ÇëÉÔºóÔÙÊÔ";
