    public void exitChat() {
        try {
            dos.writeUTF(username + "@exit" + getThreadID() + "@exit");
            flag_exit = false;
            System.exit(0);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
    public void exitLogin() {
        System.exit(0);
    }
    public void exitClient() {
        flag_exit = false;
        System.exit(0);
    }
}
